# schemas.py
from pydantic import BaseModel

# `job_id` is generated by the browser so it can start polling
# GET /api/progress/{job_id} the moment the request goes out, without waiting for
# a response to learn the id. It is optional: a request without one simply
# reports no progress.

class SummarizeRequest(BaseModel):
    text: str
    job_id: str | None = None

class QARequest(BaseModel):
    question: str
    context: str
    job_id: str | None = None
